#!/usr/bin/env bash
# PreToolUse hook: the brain may write only under nodes/ and memory/ of this vault.
# index/ and .synapse/ are generated by the Synapse app. Wired in .claude/settings.json. Requires: jq.
set -uo pipefail
input="$(cat)"
tool="$(printf '%s' "$input" | jq -r '.tool_name // ""' 2>/dev/null)" || exit 0
case "$tool" in Write|Edit|MultiEdit|NotebookEdit) ;; *) exit 0 ;; esac
path="$(printf '%s' "$input" | jq -r '.tool_input.file_path // .tool_input.notebook_path // ""' 2>/dev/null)" || exit 0
[ -n "$path" ] || exit 0

root="${CLAUDE_PROJECT_DIR:-$PWD}"
case "$path" in /*) abs="$path" ;; *) abs="$root/$path" ;; esac
ok=0
case "$abs" in *"/../"*|*"/.."|"../"*) ok=0 ;; "$root"/nodes/*|"$root"/memory/*) ok=1 ;; esac
[ "$ok" = 1 ] && exit 0

reason="Synapse vault guard: write only under nodes/ or memory/. index/ and .synapse/ are generated by the app. Blocked: $path"
jq -n --arg r "$reason" '{decision:"block", reason:$r, hookSpecificOutput:{hookEventName:"PreToolUse", permissionDecision:"deny", permissionDecisionReason:$r}}'
